import{_ as a}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as r,o as t,c as n,a2 as l}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"Willkommen","description":"MiniTavern Ultra Handbuch — mobiles AI-Roleplay, Charakterkarten, BYOK, Ollama/LM Studio auf iOS/Android.","frontmatter":{"title":"Willkommen","description":"MiniTavern Ultra Handbuch — mobiles AI-Roleplay, Charakterkarten, BYOK, Ollama/LM Studio auf iOS/Android.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Willkommen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra Handbuch — mobiles AI-Roleplay, Charakterkarten, BYOK, Ollama/LM Studio auf iOS/Android."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de"}]]},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md","lastUpdated":1787224147000}'),i={name:"de/index.md"};function o(d,e,s,u,h,g){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="willkommen" tabindex="-1">Willkommen <a class="header-anchor" href="#willkommen" aria-label="Permalink to &quot;Willkommen&quot;">​</a></h1><div class="overview-hero"><p><img src="'+a+'" alt="MiniTavern Ultra"></p></div><h2 id="uber-die-app" tabindex="-1">Über die App <a class="header-anchor" href="#uber-die-app" aria-label="Permalink to &quot;Über die App&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> ist eine <strong>AI-Rollenspiel-Chat-App</strong>.</p><p><strong>Begleiter erschaffen. Geschichte spielen.</strong> — eine Charakterkarte, zwei Einstiege.</p><p>Importieren oder erstellen Sie Charakterkarten, verbinden Sie Cloud- oder lokale Modelle per <strong>BYOK</strong>. Schlüssel und Daten bleiben zuerst auf Ihrem Gerät.</p><h2 id="was-sie-tun-konnen" tabindex="-1">Was Sie tun können <a class="header-anchor" href="#was-sie-tun-konnen" aria-label="Permalink to &quot;Was Sie tun können&quot;">​</a></h2><ol><li><p><strong>Eigenen AI-Begleiter gestalten</strong><br> Persönlichkeit, Sprechweise und Beziehung — geeignet für Austausch, Begleitung, Alltag.</p></li><li><p><strong>Lieblingsfiguren und Kanon «zurückholen»</strong><br> Community-Karten (SillyTavern-freundlich) importieren und in vertrautem Ton weiterspielen.</p></li><li><p><strong>Geschichten und lange Plots</strong><br> Lorebook für Settings, Regex für die Darstellung; Session mit eigenem Modell und Optik.</p></li><li><p><strong>Eigene Modelle, eigenes Tempo</strong><br><strong>BYOK</strong>: eigener API Key zu Cloud-Diensten oder Ollama / LM Studio zu Hause. Ohne bezahltes Kontingent: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>; lokal: <a href="/ultra_guides/de/local/">Lokale Modelle</a>.</p></li></ol><h2 id="warum-minitavern" tabindex="-1">Warum MiniTavern <a class="header-anchor" href="#warum-minitavern" aria-label="Permalink to &quot;Warum MiniTavern&quot;">​</a></h2><ul><li><strong>Eine Karte, zwei Öffnungen</strong>: Alltag oder Immersion, gleicher Einstieg</li><li><strong>Karten zuerst</strong>: PNG / JSON Import und Vorschau</li><li><strong>Private APIs</strong>: Schlüssel unter Ihrer Kontrolle</li><li><strong>Fortgeschritten</strong>: Lorebook, Regex, Persona, interaktive Kartenflächen</li><li><strong>Daten mitnehmen</strong>: Backup und Einzelchat-Archive</li></ul><h2 id="schnellstart" tabindex="-1">Schnellstart <a class="header-anchor" href="#schnellstart" aria-label="Permalink to &quot;Schnellstart&quot;">​</a></h2><ol><li><strong>Modell</strong>: Einstellungen → <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a> → Neu, testen, Standard.</li><li><strong>Charakter</strong>: Charakterkarten → <a href="/ultra_guides/de/manual/chara-card">importieren oder erstellen</a>.</li><li><strong>Chatten</strong>: vom Charakter aus — Begleitung oder Rolle, Ihre Wahl.</li></ol><p>Details: <a href="/ultra_guides/de/manual/getting-started">Erste Schritte</a>. Lokal: <a href="/ultra_guides/de/local/">Übersicht</a> · <a href="/ultra_guides/de/quickstart">Sprach-Quickstart</a> · <a href="/ultra_guides/de/local/image-gen/">Bild</a>. Free: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>.</p><h2 id="handbuch-einstiege" tabindex="-1">Handbuch-Einstiege <a class="header-anchor" href="#handbuch-einstiege" aria-label="Permalink to &quot;Handbuch-Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Hinweis</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/manual/">Handbuch</a></td><td>Lesereihenfolge und Überblick</td></tr><tr><td><a href="/ultra_guides/de/manual/model-link">Modelle</a></td><td>Verbindung, Parameter, Test, Fehler</td></tr><tr><td><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a></td><td>Free-/Trial-Kontingente und Key-Eintrag</td></tr><tr><td><a href="/ultra_guides/de/local/">Lokale Modelle</a></td><td>Sprache / Bild lokal</td></tr><tr><td><a href="/ultra_guides/de/manual/chara-card">Charaktere</a></td><td>Import, Bearbeiten, Chatstart</td></tr><tr><td><a href="/ultra_guides/de/manual/chat">Chat</a></td><td>Dialog und Session-Einstellungen</td></tr><tr><td><a href="/ultra_guides/de/manual/lorebook">Fortgeschritten</a></td><td>Lorebook, Regex, Persona, Backup</td></tr></tbody></table><p>In der App: Einstellungen → <strong>Hilfe &amp; Feedback</strong> → <strong>Benutzerhandbuch</strong>.</p><h2 id="faq-kurz" tabindex="-1">FAQ (Kurz) <a class="header-anchor" href="#faq-kurz" aria-label="Permalink to &quot;FAQ (Kurz)&quot;">​</a></h2><p><strong>Q: Was ist MiniTavern Ultra?</strong><br> A: Eine AI-Roleplay-Chat-App. Eigene Begleiter oder importierte Karten; eigener API Key oder lokales Modell.</p><p><strong>Q: Werden Daten auf eure Server hochgeladen?</strong><br> A: Chat, Charaktere und Schlüssel bleiben standardmäßig auf dem Gerät; Modell-Requests gehen an Ihre konfigurierten Dritt- oder Lokaladressen. Siehe <a href="/ultra_guides/de/privacy">Datenschutz</a>.</p><p><strong>Q: Geht es ohne API?</strong><br> A: Cloud-Key selbst beschaffen oder nach <a href="/ultra_guides/de/local/">Lokale Modelle</a> am PC aufsetzen und das Handy verbinden. Free: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>; lokales Bild: <a href="/ultra_guides/de/local/image-gen/">Bildmodelle</a>.</p><h2 id="download-rechtliches" tabindex="-1">Download &amp; Rechtliches <a class="header-anchor" href="#download-rechtliches" aria-label="Permalink to &quot;Download &amp; Rechtliches&quot;">​</a></h2><ul><li>Kopfzeile <strong>MiniTavern herunterladen</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">Produktwebsite</a></li><li><a href="/ultra_guides/de/privacy">Datenschutz</a> · <a href="/ultra_guides/de/terms">Nutzungsbedingungen</a></li></ul>',22)])])}const b=r(i,[["render",o]]);export{p as __pageData,b as default};
